import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Card, CardContent, Typography, Grid, Avatar, Button, TextField } from "@mui/material";
import axios from "axios";

function Login() {
    const navigate = useNavigate();
    const [formData, setFormData] = useState({ numElecteur: "", numCNI: "" });
    const [errorMessage, setErrorMessage] = useState("");

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setErrorMessage(""); // Réinitialiser le message d'erreur

        try {
            const res = await axios.post("http://localhost:5000/api/login-elector", formData);
            if (res.data.success) {
                console.log("Données envoyées à VerifyOTP:", res.data.elector);
                navigate("/verify-otp", { state: { ...res.data.elector, numElecteur: formData.numElecteur } });
            } else {
                setErrorMessage("Numéro d’électeur ou CNI incorrect.");
            }
        } catch (error) {
            console.error("Erreur:", error);
            setErrorMessage("Erreur de connexion au serveur.");
        }
    };

    return (
        <Grid container justifyContent="center" alignItems="center" style={{ minHeight: "100vh" }}>
            <Card style={{ padding: 20, maxWidth: 400 }}>
                <CardContent>
                    <Typography variant="h5" align="center">
                        Connexion
                    </Typography>
                    {errorMessage && <Typography color="error" align="center">{errorMessage}</Typography>}
                    <form onSubmit={handleSubmit}>
                        <TextField
                            label="Numéro d’électeur"
                            name="numElecteur"
                            fullWidth
                            margin="normal"
                            onChange={handleChange}
                            required
                        />
                        <TextField
                            label="Numéro CNI"
                            name="numCNI"
                            fullWidth
                            margin="normal"
                            onChange={handleChange}
                            required
                        />
                        <Button type="submit" variant="contained" color="primary" fullWidth>
                            Se connecter
                        </Button>
                    </form>
                </CardContent>
            </Card>
        </Grid>
    );
}

export default Login;
